const items = $input.all();

function getField(f, ...keys) {
  for (const k of keys) {
    if (f[k] !== undefined && f[k] !== null && String(f[k]).trim() !== '') {
      return f[k];
    }
  }
  return '';
}

function toNumber(value) {
  if (value === undefined || value === null || String(value).trim() === '') return null;
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
}

function parseTimestamp(value) {
  const match = String(value || '').trim().match(/^(\d{2,}):(\d{2}):(\d{2})(?:\.(\d{1,3}))?$/);
  if (!match) return null;
  const hours = Number(match[1]);
  const minutes = Number(match[2]);
  const seconds = Number(match[3]);
  const milliseconds = Number((match[4] || '0').padEnd(3, '0'));
  if (minutes > 59 || seconds > 59) return null;
  return hours * 3600 + minutes * 60 + seconds + milliseconds / 1000;
}

const output = [];
for (const item of items) {
  const f = item.json;

  const rawConfirm =
    f['anonymised_data_confirmation'] !== undefined
      ? f['anonymised_data_confirmation']
      : f['I confirm this submission is anonymised or synthetic and approved for this workflow'];

  const confirmed =
    rawConfirm === true ||
    (Array.isArray(rawConfirm) && rawConfirm.length > 0) ||
    ['true', 'on', 'yes', 'confirmed', 'i confirm'].some((v) =>
      String(rawConfirm ?? '').toLowerCase().trim().includes(v)
    );

  if (!confirmed) {
    throw new Error('Submission stopped: confirm that the data is synthetic or anonymised and approved for this workflow.');
  }

  const mapped = {
    session_id: getField(f, 'session_id', 'Session ID'),
    subject: getField(f, 'subject', 'Subject'),
    candidate_id: getField(f, 'candidate_id', 'Candidate ID'),
    start_timestamp: getField(f, 'start_timestamp', 'Start Timestamp (HH:MM:SS.mmm)', 'Start Timestamp'),
    end_timestamp: getField(f, 'end_timestamp', 'End Timestamp (HH:MM:SS.mmm)', 'End Timestamp'),
    hook: getField(f, 'hook', 'Proposed 3-second Hook', 'Hook'),
    moment_bucket: getField(f, 'moment_bucket', 'Moment Bucket'),
    verbatim_dialogue: getField(f, 'verbatim_dialogue', 'Anonymised Verbatim Dialogue', 'Verbatim Dialogue'),
    parent_value_score: getField(f, 'parent_value_score', 'Parent Value Score (0-2)', 'Parent Value Score'),
    hook_score: getField(f, 'hook_score', 'Hook Score (0-2)', 'Hook Score'),
    participation_score: getField(f, 'participation_score', 'Participation Score (0-2)', 'Participation Score'),
    emotion_score: getField(f, 'emotion_score', 'Emotion Score (0-1)', 'Emotion Score'),
    visual_score: getField(f, 'visual_score', 'Visual Score (0-1)', 'Visual Score'),
    audio_score: getField(f, 'audio_score', 'Audio Score (0-1)', 'Audio Score'),
    mute_readability_score: getField(f, 'mute_readability_score', 'Mute Readability Score (0-1)', 'Mute Readability Score'),
    geography_fit: getField(f, 'geography_fit', 'Geography Fit'),
    compliance_flags: getField(f, 'compliance_flags', 'Compliance Flags (no identifying details)', 'Compliance Flags'),
    visual_verification: getField(f, 'visual_verification', 'Visual Verification'),
    hard_exclusion_status: getField(f, 'hard_exclusion_status', 'Hard Exclusion Identified?', 'Hard Exclusion'),
    consent_status: getField(f, 'consent_status', 'Guardian Marketing Consent', 'Consent Status'),
    privacy_review_status: getField(f, 'privacy_review_status', 'Privacy Review', 'Privacy Review Status'),
    context_review_status: getField(f, 'context_review_status', 'Cultural / Context Review', 'Context Review Status'),
    editor_instructions: getField(f, 'editor_instructions', 'Editor Instructions')
  };

  const required = [
    'session_id', 'subject', 'candidate_id', 'start_timestamp', 'end_timestamp',
    'hook', 'moment_bucket', 'verbatim_dialogue', 'geography_fit', 'compliance_flags',
    'visual_verification', 'hard_exclusion_status', 'consent_status',
    'privacy_review_status', 'context_review_status', 'editor_instructions'
  ];
  const missing = required.filter((key) => !String(mapped[key] ?? '').trim());
  if (missing.length) throw new Error('Missing required fields: ' + missing.join(', '));

  const start = parseTimestamp(mapped.start_timestamp);
  const end = parseTimestamp(mapped.end_timestamp);
  if (start === null || end === null || end <= start) {
    throw new Error('Invalid timestamp range. Use HH:MM:SS.mmm and ensure end is after start.');
  }
  const duration = Number((end - start).toFixed(3));
  if (duration < 10 || duration > 20) {
    throw new Error(`Candidate duration must be between 10 and 20 seconds. Received ${duration} seconds.`);
  }

  const rejected = mapped.hard_exclusion_status === 'Yes' ||
    mapped.privacy_review_status === 'Failed' ||
    mapped.visual_verification === 'Verified – Fail';

  const definitions = [
    ['Parent Value Score', 'parent_value_score', 2],
    ['Hook Score', 'hook_score', 2],
    ['Participation Score', 'participation_score', 2],
    ['Emotion Score', 'emotion_score', 1],
    ['Visual Score', 'visual_score', 1],
    ['Audio Score', 'audio_score', 1],
    ['Mute Readability Score', 'mute_readability_score', 1]
  ];
  const scoreFields = definitions.map(([label, key, maximum]) => ({
    label, value: toNumber(mapped[key]), maximum
  }));

  let totalScore = null;
  if (!rejected) {
    for (const score of scoreFields) {
      if (score.value === null || !Number.isInteger(score.value) || score.value < 0 || score.value > score.maximum) {
        throw new Error(`${score.label} must be an integer between 0 and ${score.maximum}.`);
      }
    }
    totalScore = scoreFields.reduce((sum, score) => sum + score.value, 0);
  }

  const notes = [];
  let decision = 'Needs Review';
  if (rejected) {
    decision = 'Rejected';
    notes.push('Hard exclusion, failed privacy review, or failed visual verification. Scores and dialogue are withheld for this rejected record. Do not use in advertising.');
  } else {
    if (mapped.visual_verification !== 'Verified – Pass') notes.push('Human audio-visual verification is pending.');
    if (mapped.consent_status !== 'Confirmed') notes.push('Guardian marketing consent is not confirmed.');
    if (mapped.privacy_review_status !== 'Passed') notes.push('Privacy review is not marked as passed.');
    if (mapped.context_review_status === 'Pending') notes.push('Cultural/context review is pending.');
    if (totalScore < 7) notes.push('Score is below the 7/10 threshold; any exception requires documented human review.');
    if (notes.length === 0) {
      decision = 'Eligible for Editor Review';
      notes.push('Configured intake gates passed. This is not final advertising approval; authorised human approval and final creative QA remain mandatory.');
    }
  }

  const row = {
    'Session ID': String(mapped.session_id).trim(),
    'Subject': String(mapped.subject).trim(),
    'Candidate ID': String(mapped.candidate_id).trim(),
    'Start Timestamp': String(mapped.start_timestamp).trim(),
    'End Timestamp': String(mapped.end_timestamp).trim(),
    'Duration': duration,
    'Hook': String(mapped.hook).trim(),
    'Moment Bucket': String(mapped.moment_bucket).trim(),
    'Verbatim Dialogue': rejected ? '[REDACTED — rejected record; do not reproduce]' : String(mapped.verbatim_dialogue).trim(),
    'Parent Value Score': rejected ? '' : scoreFields[0].value,
    'Hook Score': rejected ? '' : scoreFields[1].value,
    'Participation Score': rejected ? '' : scoreFields[2].value,
    'Emotion Score': rejected ? '' : scoreFields[3].value,
    'Visual Score': rejected ? '' : scoreFields[4].value,
    'Audio Score': rejected ? '' : scoreFields[5].value,
    'Mute Readability Score': rejected ? '' : scoreFields[6].value,
    'Total Score': rejected ? '' : totalScore,
    'Geography Fit': String(mapped.geography_fit).trim(),
    'Compliance Flags': String(mapped.compliance_flags).trim(),
    'Visual Verification': String(mapped.visual_verification).trim(),
    'Final Decision': decision,
    'Editor Instructions': String(mapped.editor_instructions).trim(),
    'Consent Status': String(mapped.consent_status).trim(),
    'Privacy Review Status': String(mapped.privacy_review_status).trim(),
    'Context Review Status': String(mapped.context_review_status).trim(),
    'Hard Exclusion': String(mapped.hard_exclusion_status).trim(),
    'Automation Gate Notes': notes.join(' '),
    'Submitted At': f.submittedAt || new Date().toISOString()
  };
  output.push({ json: row });
}
return output;
